import {loadFile} from './storage.mjs';
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const kroner=cents=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK'}).format(cents/100);
const key='pf-cart-v1';
export function readCart(){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value.filter(l=>l&&typeof l.id==='string'&&typeof l.productId==='string'):[];}catch{return [];}}
export function writeCart(lines){localStorage.setItem(key,JSON.stringify(lines));window.dispatchEvent(new Event('pf-cart-change'));}
export function putCart(line,id){const lines=readCart();if(id&&!lines.some(l=>l.id===id))throw Error('Produktet er fjernet fra kurven. Åbn det igen fra kataloget.');const result={...structuredClone(line),id:id||crypto.randomUUID()};writeCart(id?lines.map(l=>l.id===id?result:l):[...lines,result]);return result;}
export async function fetchQuote(lines){const r=await fetch('/api/pf-quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines})});if(!r.ok)throw Error('Prisen kunne ikke hentes. Prøv igen.');return r.json();}
export function priceHTML(quote){
 if(!quote)return '<p class="small muted">Beregner pris…</p>';
 if(quote.error)return `<p class="error">${escape(quote.error)}</p>`;
 if(quote.totalIncVat===null)return `<strong>Pris afventer</strong><p class="small muted">${escape(quote.message||'Prisen er endnu ikke tilgængelig.')}</p>${quote.knownIncVat>0?`<p>Kendte varelinjer: ${kroner(quote.knownIncVat)} inkl. moms</p>`:''}`;
 return `${quote.quantity?`<div class="pf-quote-unit"><span>Samlet pris pr. stk. inkl. tryk og opstart</span><strong>${kroner(Math.round(quote.totalIncVat/quote.quantity))}</strong><small>Ved ${quote.quantity} stk. · inkl. moms</small></div>`:''}<dl class="pf-price-breakdown"><div><dt>Varer</dt><dd>${kroner(quote.goods)}</dd></div><div><dt>Tryk</dt><dd>${kroner(quote.print)}</dd></div><div><dt>Opstart og tillæg</dt><dd>${kroner(quote.setup)}</dd></div><div><dt>Moms (25 %)</dt><dd>${kroner(quote.vat)}</dd></div><div class="pf-price-total"><dt>I alt inkl. moms</dt><dd>${kroner(quote.totalIncVat)}</dd></div></dl><p class="small muted">Fragt beregnes senere.</p>`;
}
let headerVersion=0;
export async function updateCartHeader(){const version=++headerVersion,lines=readCart(),badge=document.querySelector('#cart-count'),sum=document.querySelector('#pf-header-sum');if(badge)badge.textContent=lines.length;if(!sum)return;if(!lines.length){sum.textContent='';return;}sum.textContent='…';try{const q=await fetchQuote(lines);if(version!==headerVersion)return;sum.textContent=q.totalIncVat===null?'Pris afventer':kroner(q.totalIncVat);}catch{if(version===headerVersion)sum.textContent='Pris afventer';}}
export function pfCartPage(data,demoCount=0){const lines=readCart();return `<section class="wrap section pf-cart-page"><div class="section-heading"><div><p class="eyebrow">DINE VALG, SAMLET ÉT STED</p><h1>Din kurv <span class="title-count">${lines.length}</span></h1></div><a class="text-link" href="/produkter">← Shop videre</a></div>${!lines.length?'<div class="empty"><h2>Find noget, der passer til jer.</h2><p>Dine produkter, logoer og trykvalg samles her.</p><a class="button" href="/produkter">Udforsk produkterne ↗</a></div>':`<div class="cart-layout"><div>${lines.map(l=>{const p=data.products.find(p=>p.id===l.productId),v=p?.variants.find(v=>v.sku===l.sku);return `<article class="cart-item pf-cart-item" data-pf-line="${escape(l.id)}">${v?`<a class="cart-image" href="/design/${p.id}?cart=${escape(l.id)}"><img src="${escape(v.images[0])}" alt="${escape(p.name)}"></a>`:'<div></div>'}<div><p class="eyebrow">${escape(p?.brand)}</p><a class="product-title" href="/design/${escape(l.productId)}?cart=${escape(l.id)}">${escape(p?.name||'Produktet er ikke længere tilgængeligt')}</a><p class="small muted">${escape(v?.color)} ${escape(v?.size)} · ${escape(l.sku)}</p><div class="pf-cart-decorations">${l.decorations?.length?l.decorations.map(d=>`<p class="small">${escape(d.method||'Ukendt tryk')} · ${escape(d.position||'Ukendt placering')}<br>${d.logo?`<button class="text-link" data-pf-logo="${escape(d.logo.id)}" data-name="${escape(d.logo.name)}">${escape(d.logo.name)} ↓</button>`:''}${d.text?`<span>“${escape(d.text)}”</span>`:''}</p>`).join(''):'<p class="small">Uden tryk</p>'}</div><div class="pf-cart-controls"><label>Antal<input type="number" min="1" max="100000" step="1" value="${l.quantity}" data-pf-quantity="${escape(l.id)}"></label><a class="text-link" href="/design/${escape(l.productId)}?cart=${escape(l.id)}">Ret produkt og design</a><button type="button" class="text-link" data-pf-remove="${escape(l.id)}">Fjern</button></div><p class="error" data-pf-line-error></p><div data-pf-line-price class="pf-line-price" aria-live="polite">Beregner pris…</div></div></article>`;}).join('')}</div><aside class="cart-summary"><h2>Dit overblik</h2><div id="pf-cart-total" aria-live="polite">Beregner pris…</div><p class="small muted">${lines.length} varelinjer · <span id="pf-cart-pieces">${lines.reduce((n,l)=>n+Number(l.quantity||0),0)}</span> stk.</p><a class="button wide" href="/betaling">Fortsæt til betaling ↗</a><button class="text-link" id="pf-cart-download">Hent kurvoversigt ↓</button><p class="small muted">Endelig pris med fragt vises før betaling.</p></aside></div>`}${demoCount?`<p class="small"><a class="text-link" href="/demokurv">Se ${demoCount} tidligere demoprodukter i din tilbudskurv</a></p>`:''}</section>`;}
export function bindCart(data,nav,notify){if(!document.querySelector('.pf-cart-page'))return;let version=0;
 async function refresh(){const current=++version,lines=readCart();try{const q=await fetchQuote(lines);if(current!==version||!document.querySelector('#pf-cart-total'))return;document.querySelector('#pf-cart-total').innerHTML=priceHTML(q);for(const [i,l]of lines.entries()){const row=[...document.querySelectorAll('[data-pf-line]')].find(el=>el.dataset.pfLine===l.id);if(row)row.querySelector('[data-pf-line-price]').innerHTML=priceHTML(q.lines[i]);}}catch(error){if(current===version&&document.querySelector('#pf-cart-total')){document.querySelector('#pf-cart-total').textContent=error.message;document.querySelectorAll('[data-pf-line-price]').forEach(el=>el.textContent='Pris afventer');}}}
 document.querySelectorAll('[data-pf-quantity]').forEach(input=>input.onchange=()=>{const quantity=Number(input.value),lines=readCart(),line=lines.find(l=>l.id===input.dataset.pfQuantity),error=input.closest('.pf-cart-item').querySelector('[data-pf-line-error]');if(!Number.isInteger(quantity)||quantity<1||quantity>100000){error.textContent='Vælg mellem 1 og 100.000 stk.';input.value=line.quantity;return;}try{writeCart(lines.map(l=>l.id===line.id?{...l,quantity}:l));error.textContent='';document.querySelector('#pf-cart-pieces').textContent=readCart().reduce((n,l)=>n+l.quantity,0);refresh();}catch{error.textContent='Kurven kunne ikke gemmes.';input.value=line.quantity;}});
 document.querySelectorAll('[data-pf-remove]').forEach(button=>button.onclick=()=>{try{writeCart(readCart().filter(l=>l.id!==button.dataset.pfRemove));nav('/kurv');notify('Produktet er fjernet fra kurven.');}catch{notify('Kurven kunne ikke gemmes.');}});
 document.querySelectorAll('[data-pf-logo]').forEach(button=>button.onclick=async()=>{const file=await loadFile(button.dataset.pfLogo);if(!file){notify('Logofilen mangler. Åbn designet og upload igen.');return;}download(file,button.dataset.name);});
 document.querySelector('#pf-cart-download')?.addEventListener('click',async()=>{try{const lines=readCart(),quote=await fetchQuote(lines);download(new Blob([JSON.stringify({status:'Lokal kurv – ikke bestilt',createdAt:new Date().toISOString(),lines,quote,note:'Logofiler vedlægges separat.'},null,2)],{type:'application/json'}),'smerch-kurv.json');}catch(error){notify(error.message);}});refresh();
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
